package com.guardianlab.chat

import android.app.*
import android.content.Intent
import android.os.*
import android.media.AudioAttributes
import android.media.RingtoneManager
import java.util.concurrent.Executors

class MessageAlerts:Service(){
 private val handler=Handler(Looper.getMainLooper());private val worker=Executors.newSingleThreadExecutor();@Volatile private var busy=false;private var ringingId:String?=null
 private val prefs by lazy {getSharedPreferences("account",MODE_PRIVATE)}
 private fun visible()=getSystemService(ActivityManager::class.java).runningAppProcesses?.any {it.pid==android.os.Process.myPid()&&it.importance==ActivityManager.RunningAppProcessInfo.IMPORTANCE_FOREGROUND}==true
 private fun incoming(api:ChatApi){val manager=getSystemService(NotificationManager::class.java);val calls=api.request("/calls").getJSONArray("calls");var incoming:org.json.JSONObject?=null;val own=prefs.getString("id","");for(i in 0 until calls.length()){val c=calls.getJSONObject(i);if(c.optString("state")=="ringing"&&c.optString("recipient")==own&&c.optString("id")!=prefs.getString("declinedCall","")){incoming=c;break}}
  if(incoming==null||visible()||!prefs.getBoolean("incomingCalls",true)){manager.cancel(880001);ringingId=null;return};val id=incoming.getString("id");if(ringingId==id)return;ringingId=id
  val open=Intent(this,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("incomingCallId",id).putExtra("peer",incoming.getString("peer")).putExtra("peerName",incoming.optString("peer_name"));val tap=PendingIntent.getActivity(this,880001,open,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val reject=PendingIntent.getBroadcast(this,880002,Intent(this,CallActionsReceiver::class.java).putExtra("callId",id),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
  val n=Notification.Builder(this,"incoming_calls").setSmallIcon(android.R.drawable.sym_action_call).setContentTitle("Incoming GuardianChat call").setContentText(incoming.optString("peer_name","Contact")).setCategory(Notification.CATEGORY_CALL).setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(tap).setOngoing(true).setTimeoutAfter(45000).addAction(Notification.Action.Builder(android.R.drawable.sym_action_call,"Open call",tap).build()).addAction(Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Decline",reject).build()).build();n.flags=n.flags or Notification.FLAG_INSISTENT;manager.notify(880001,n)
 }
 private val poll=object:Runnable {override fun run(){if(!busy){busy=true;worker.execute {try{val token=prefs.getString("token","")!!;if(token.isEmpty()){stopSelf();return@execute};val api=ChatApi(prefs.getString("server","")!!,token);incoming(api);val inbox=api.request("/inbox").getJSONArray("ids");if(inbox.length()>0)api.request("/delivered",org.json.JSONObject().put("ids",inbox));val users=api.request("/users").getJSONArray("users");val primed=prefs.getBoolean("alertsPrimed",false);for(i in 0 until users.length()){val u=users.getJSONObject(i);val id=u.getString("id");val latest=u.optLong("latest");val old=prefs.getLong("alert-$id",0);if(u.optInt("unread")==0)getSystemService(NotificationManager::class.java).cancel(id.hashCode());if(prefs.getBoolean("notifications",false)&&primed&&latest>old&&u.optInt("unread")>0&&!visible()){val tap=PendingIntent.getActivity(this@MessageAlerts,id.hashCode(),Intent(this@MessageAlerts,MainActivity::class.java).putExtra("peer",id).putExtra("peerName",u.getString("name")),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val n=Notification.Builder(this@MessageAlerts,"messages").setSmallIcon(android.R.drawable.ic_dialog_email).setContentTitle("GuardianChat").setContentText("New message from ${u.getString("name")}").setNumber(u.optInt("unread")).setContentIntent(tap).setAutoCancel(true).build();getSystemService(NotificationManager::class.java).notify(id.hashCode(),n)};prefs.edit().putLong("alert-$id",latest).apply()};prefs.edit().putBoolean("alertsPrimed",true).apply()}catch(_:Exception){getSystemService(NotificationManager::class.java).cancel(880001);ringingId=null}finally{busy=false}}};handler.postDelayed(this,5000)}}
 override fun onCreate(){super.onCreate();val manager=getSystemService(NotificationManager::class.java);manager.createNotificationChannel(NotificationChannel("connection","Wi-Fi notification connection",NotificationManager.IMPORTANCE_LOW));manager.createNotificationChannel(NotificationChannel("messages","New messages",NotificationManager.IMPORTANCE_HIGH));val channel=NotificationChannel("incoming_calls","Incoming calls",NotificationManager.IMPORTANCE_HIGH);channel.setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE),AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION_RINGTONE).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());channel.enableVibration(true);manager.createNotificationChannel(channel);val tap=PendingIntent.getActivity(this,0,Intent(this,MainActivity::class.java),PendingIntent.FLAG_IMMUTABLE);startForeground(7,Notification.Builder(this,"connection").setSmallIcon(android.R.drawable.sym_action_call).setContentTitle("GuardianChat connection active").setContentText("Listening for calls and messages on your Mac’s Wi-Fi server").setContentIntent(tap).setOngoing(true).build());handler.post(poll)}
 override fun onStartCommand(intent:Intent?,flags:Int,startId:Int)=START_STICKY
 override fun onBind(intent:Intent?)=null
 override fun onTimeout(startId:Int,fgsType:Int){stopSelf()}
 override fun onDestroy(){handler.removeCallbacksAndMessages(null);getSystemService(NotificationManager::class.java).cancel(880001);worker.shutdown();super.onDestroy()}
}
